// === Tab: mySketch.js ===
// 核心参数设置
let tideY;           // 当前水面实际Y坐标
let targetTideY;     // 目标水面Y坐标（跟随鼠标）
let noiseOffset = 0; // 控制海浪横向滚动的变量
let gridSize = 16;   // 字符海的密度（数字越大越稀疏，呼吸感越强）

// 夏日漱石 (Summer Salt) 歌词排版
const lyricsLines = [
  "Summer days will pass you by",
  "But we're just soaking in the sun",
  "Waiting for the tide to turn",
  "In this orange sea of ours",
  "Revvin' up the engine, driving to the coast",
  "Leave the heavy world behind"
];

// 构成海水的字符库（排除了太宽的字母，保持视觉整洁）
const seaChars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789.,:;";

function setup() {
  createCanvas(windowWidth, windowHeight);
  // 初始化水面在屏幕下方
  tideY = height * 0.8;
  targetTideY = height * 0.8;

  noCursor(); // 隐藏默认鼠标箭头
  textFont('Georgia'); // 使用带有一点复古诗意的衬线字体
}

function draw() {
  // 1. 绘制沙滩背景 (非常淡的暖灰色)
  background('#F7F5F0'); 

  // 2. 绘制沙滩上的歌词 (一次性排布好)
  drawLyrics();

  // 3. 计算潮汐的平滑移动
  // 限制鼠标控制范围，不让水完全消失或完全淹没屏幕
  let constrainedMouseY = constrain((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), height * 0.1, height * 0.95);
  // 使用 lerp 让水面“缓慢、有阻力地”追随鼠标，而不是瞬间跳转
  targetTideY = constrainedMouseY;
  tideY = lerp(tideY, targetTideY, 0.05); 

  // 海浪随时间向左流动的速度
  noiseOffset += 0.005; 

  // 4. 绘制字符橘子海
  drawCharacterSea();
}

// === 绘制歌词层 ===
function drawLyrics() {
  textAlign(CENTER, CENTER);
  let startY = height * 0.3; // 歌词起始高度
  let lineSpacing = 45;      // 行距

  for (let i = 0; i < lyricsLines.length; i++) {
    let yPos = startY + i * lineSpacing;

    // 给歌词一点淡淡的阴影，模仿刻在沙子上的质感
    fill('#E2DDD5');
    text(lyricsLines[i], width / 2 + 1, yPos + 1);

    // 歌词主体颜色 (复古棕灰)
    fill('#8E8578'); 
    textSize(22);
    text(lyricsLines[i], width / 2, yPos);
  }
}

// === 绘制核心：字符橘子海 ===
function drawCharacterSea() {
  textAlign(CENTER, CENTER);
  textSize(gridSize * 0.85); // 字体略小于网格，留出呼吸感空隙
  noStroke();

  // 遍历整个屏幕的网格
  for (let x = 0; x <= width; x += gridSize) {

    // 利用柏林噪声(Perlin Noise)计算这一列的海浪高度
    // 叠加两层噪声让波浪更自然（主波浪+细碎波浪）
    let wave1 = noise(x * 0.002, noiseOffset) * 150;
    let wave2 = noise(x * 0.008, noiseOffset * 1.5) * 40;
    // waveEdge 是这条虚拟的海浪分界线
    let waveEdge = tideY + (wave1 + wave2 - 95); 

    for (let y = 0; y <= height; y += gridSize) {

      // 只有当网格点位于海浪线之下时，才绘制海水字符
      if (y > waveEdge) {

        // 计算当前字符距离水面的“深度”
        let depth = y - waveEdge;

        // 【关键】基于坐标生成伪随机索引，保证字符位置固定不闪烁
        let charIndex = floor(noise(x * 0.1, y * 0.1) * seaChars.length);
        let charToDraw = seaChars.charAt(charIndex);

        // --- 颜色计算 (橘子海渐变) ---
        let c;
        if (depth < 30) {
          // 浅水区 / 浪尖区：明亮的白金色过渡到橘黄色
          let inter = map(depth, 0, 30, 0, 1);
          c = lerpColor(color('#FFF2D4'), color('#FFB74D'), inter);

          // 在浪尖加入随机的“波光粼粼”高光效果
          let sparkle = noise(x * 0.05, y * 0.05, frameCount * 0.05);
          if (sparkle > 0.75) c = color('#FFFFFF'); 

        } else if (depth < 150) {
          // 中层水区：橘黄色过渡到深橘红色
          const inter = map(depth, 30, 150, 0, 1);
          c = lerpColor(color('#FFB74D'), color('#F57C00'), inter);
        } else {
          // 深水区：深橘红色往下延伸
          const inter = map(depth, 150, height, 0, 1);
          inter = constrain(inter, 0, 1);
          c = lerpColor(color('#F57C00'), color('#bf360c'), inter);
        }

        fill(c);

        // 绘制字符
        // 加入一点极其微小的y轴正弦偏移，让水下的字符有微微的水波扭曲感
        let subtleWobble = sin(frameCount * 0.02 + y * 0.1) * 2;
        text(charToDraw, x, y + subtleWobble);
      }
    }
  }
}

// 确保在窗口调整大小时画面不会崩坏
function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

